INSERT INTO "public"."resources" ("id", "user_id", "type", "metadata", "created_at") VALUES
	('8d3a3572-7585-4819-a10d-6bb0767f1bc6', '702a2ebf-569e-4f7d-a7df-78e7c1847000', 'lora', '{"Name": "Recursive Magic", "Author": "kabachuha", "Images": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492287047-4hsa81jq.mp4", "type": "video", "alt_text": "1 (2).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492288384-qt5m9zdp.png", "type": "image", "alt_text": "videoframe_2494.png"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492289008-35tg43uu.mp4", "type": "video", "alt_text": "3 (2).mp4"}], "Model ID": "fractal-t2v.safetensors", "filename": "fractal-t2v.safetensors", "is_public": true, "lora_type": "Wan 2.1 14b", "base_model": "Wan 2.1 T2V", "created_by": {"is_you": false, "username": "kabachuha"}, "Description": "This t2v LoRA was trained on various fractal zooms, self-similarity and Droste effects and aims to help you replicate those dizzying experiences with custom items or persons.\n\nBecause it''s a t2v model, it works plug-and-play with LoRAs and VACE. The videos present are both with vanilla text2video and with VACE reference insertion. (4/1)\n\nAll the videos here were created without loop forcing in the workflow - in form of flf2v or otherwise! (emergent ability?)\n\nThis LoRA is quite experimental, and the dataset may be too diverse to focus fully. The anatomy can get really weird here, and it''s maybe a feature. (Check out the fractal hands!) It also has a slight cool colors and 3D model look bias.\n\nThere may be a version two in the future, though I think it''s already looking dope enough.\n\nThe trigger word is \"fractal help\".\n\nSome example prompts:\n\nfractal help. This animation shows an anime girl sitting still on a chair and holding a smartphone with an image of the anime girl herself sitting on a chair and holding a smartphone. The camera zooms in, showing the anime girl inside the smartphone holding another smartphone with the with an image of the anime girl herself sitting on a chair and holding a smartphone. The camera continues to zoom in, forming a perfect loop.\nfractal help. This animation shows a wooden table standing on a gigantic wooden table. The table is holding a miniature version of itself. The camera zooms in showing this miniature table version holding even smaller miniature table version of itself. The camera zooms in further, completing a perfect loop. The background is a home interior.\nLeave a comment if you''d like to provide feedback or ask for usage tips.", "Model Files": [{"url": "https://huggingface.co/peteromallet/ad_motion_loras/resolve/main/fractal-t2v.safetensors", "path": "fractal-t2v.safetensors"}], "trigger_word": "fractal help", "Last Modified": "2025-07-26T01:11:29.375Z", "huggingface_url": "https://huggingface.co/peteromallet/ad_motion_loras/resolve/main/fractal-t2v.safetensors", "main_generation": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492287047-4hsa81jq.mp4", "sample_generations": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492287047-4hsa81jq.mp4", "type": "video", "alt_text": "1 (2).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492288384-qt5m9zdp.png", "type": "image", "alt_text": "videoframe_2494.png"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492289008-35tg43uu.mp4", "type": "video", "alt_text": "3 (2).mp4"}]}', '2025-07-26 01:11:29.610195+00'),
	('ba226e88-4594-4174-9910-b98b492d5a40', '702a2ebf-569e-4f7d-a7df-78e7c1847000', 'lora', '{"Name": "Wallace & Gromit", "Author": "Cseti", "Images": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753109868700-pepfikgk.mp4", "type": "video", "alt_text": "singles_00001.mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753109869212-vd27ltrt.mp4", "type": "video", "alt_text": "singles_00003.mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753109869756-aot3iky0.mp4", "type": "video", "alt_text": "singles_00006.mp4"}], "Model ID": "302144-wan14b-walgro-e180.safetensors", "filename": "302144-wan14b-walgro-e180.safetensors", "is_public": true, "lora_type": "Wan 2.1 14b", "base_model": "Wan 2.1 T2V", "created_by": {"is_you": true}, "Model Files": [{"url": "https://huggingface.co/Cseti/wan-14b-wallace_and_gromit-style-lora-v1/resolve/main/302144-wan14b-walgro-e180.safetensors", "path": "302144-wan14b-walgro-e180.safetensors"}], "trigger_word": "walgro style", "Last Modified": "2025-07-21T14:57:50.236Z", "huggingface_url": "https://huggingface.co/Cseti/wan-14b-wallace_and_gromit-style-lora-v1/resolve/main/302144-wan14b-walgro-e180.safetensors", "main_generation": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753109868700-pepfikgk.mp4", "sample_generations": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753109868700-pepfikgk.mp4", "type": "video", "alt_text": "singles_00001.mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753109869212-vd27ltrt.mp4", "type": "video", "alt_text": "singles_00003.mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753109869756-aot3iky0.mp4", "type": "video", "alt_text": "singles_00006.mp4"}]}', '2025-07-21 14:57:50.459062+00'),
	('c3a349f6-e5e6-44f5-9c02-ff517ad0ec28', '8a9fdac5-ed89-482c-aeca-c3dd7922d53c', 'lora', '{"Name": "Recursive Magic", "Author": "kabachuha", "Images": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492287047-4hsa81jq.mp4", "type": "video", "alt_text": "1 (2).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492288384-qt5m9zdp.png", "type": "image", "alt_text": "videoframe_2494.png"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492289008-35tg43uu.mp4", "type": "video", "alt_text": "3 (2).mp4"}], "Model ID": "fractal-t2v.safetensors", "filename": "fractal-t2v.safetensors", "is_public": true, "lora_type": "Wan 2.1 14b", "base_model": "Wan 2.1 T2V", "created_by": {"is_you": false, "username": "kabachuha"}, "Description": "This t2v LoRA was trained on various fractal zooms, self-similarity and Droste effects and aims to help you replicate those dizzying experiences with custom items or persons.\n\nBecause it''s a t2v model, it works plug-and-play with LoRAs and VACE. The videos present are both with vanilla text2video and with VACE reference insertion. (4/1)\n\nAll the videos here were created without loop forcing in the workflow - in form of flf2v or otherwise! (emergent ability?)\n\nThis LoRA is quite experimental, and the dataset may be too diverse to focus fully. The anatomy can get really weird here, and it''s maybe a feature. (Check out the fractal hands!) It also has a slight cool colors and 3D model look bias.\n\nThere may be a version two in the future, though I think it''s already looking dope enough.\n\nThe trigger word is \"fractal help\".\n\nSome example prompts:\n\nfractal help. This animation shows an anime girl sitting still on a chair and holding a smartphone with an image of the anime girl herself sitting on a chair and holding a smartphone. The camera zooms in, showing the anime girl inside the smartphone holding another smartphone with the with an image of the anime girl herself sitting on a chair and holding a smartphone. The camera continues to zoom in, forming a perfect loop.\nfractal help. This animation shows a wooden table standing on a gigantic wooden table. The table is holding a miniature version of itself. The camera zooms in showing this miniature table version holding even smaller miniature table version of itself. The camera zooms in further, completing a perfect loop. The background is a home interior.\nLeave a comment if you''d like to provide feedback or ask for usage tips.", "Model Files": [{"url": "https://huggingface.co/peteromallet/ad_motion_loras/resolve/main/fractal-t2v.safetensors", "path": "fractal-t2v.safetensors"}], "trigger_word": "fractal help", "Last Modified": "2025-07-26T01:11:29.375Z", "huggingface_url": "https://huggingface.co/peteromallet/ad_motion_loras/resolve/main/fractal-t2v.safetensors", "main_generation": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492287047-4hsa81jq.mp4", "sample_generations": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492287047-4hsa81jq.mp4", "type": "video", "alt_text": "1 (2).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492288384-qt5m9zdp.png", "type": "image", "alt_text": "videoframe_2494.png"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492289008-35tg43uu.mp4", "type": "video", "alt_text": "3 (2).mp4"}]}', '2025-07-26 01:14:45.028654+00'),
	('0ac20915-bb2c-4a6b-9878-77c3622135c4', '8a9fdac5-ed89-482c-aeca-c3dd7922d53c', 'lora', '{"Name": "Claymation Transformation", "Author": " kabachuha", "Images": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492711541-y52jcqqr.mp4", "type": "video", "alt_text": "3 (3).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492712139-yhuhp9dn.mp4", "type": "video", "alt_text": "2 (3).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492712588-a6j8mwkj.mp4", "type": "video", "alt_text": "1 (3).mp4"}], "Model ID": "plasticine-t2v.safetensors", "filename": "plasticine-t2v.safetensors", "is_public": true, "lora_type": "Wan 2.1 14b", "base_model": "Wan 2.1 T2V", "created_by": {"is_you": false, "username": " kabachuha"}, "Description": "Where objects melt, stretch, and squish into something entirely new!\n\nThis LoRA replicates the surreal, handcrafted look of plasticine/claymation animations, where objects morph into others with stop-motion fluidity. Perfect for whimsical transformations.\n\nWorks great both standalone and with VACE for first-last-frame selection and image to video!\n\nThe examples illustrate each mode: 3 x pure text2video, 2 x image2video (set start, set end), 1 x flf2video (interpolation).\n\nThe generation resolution is advised to be 480p or close (e.g. 512x512). The trained durations are from 1 to 5 seconds, with the most tested one of 3 seconds. (48 frames)\n\nThe t2v training was made using diffusion-pipe for 135 epochs and flow shift of 4.0 on the dataset of metamorphoses from the legendary plasticine animation \"Last Year''s Snow Was Falling\".\n\nDue to the specifics of the train material, you may sometimes encounter a hut-like interior with four-sectional windows in the default mode, so it''s encouraged to write the background appearance in the text2video mode manually. Though less often, some parts of the main character''s appearance can happen (like the villager hat), in this case add ''lys-man'' to the negative prompt.\n\nFor text2video I tested with cfg 6.0, shift 5.0. For image2video/flf2video recommended to use with the kijai VACE workflows, standard 1.0 lora weight, 6.0 cfg, 16.0 shift + cfg_zero_star. (see videos meta)\n\nThe trigger words are ''Claymation transformation'' and ''plasticine-transforms''. The best prompts are:\n\nClaymation transformation. The video begins with an [object] standing before a [describe background]. [optional object description]. Then the [object] plasticine-transforms into an [another object, object description].\nSimplified:\n\nClaymation transformation. The video begins with an [object]. Then the [object] plasticine-transforms into [another object].\nBonus. You can specify multiple transformations in the same video!\n\nClaymation transformation. The video begins with an [subject] sitting on a table. Then the [subject] [does triggering action]. The [subject] squishes, shrinks and the [subject] then plasticine-transforms into an [object_1], which then plasticine-melts into a [object_2].\nThis LoRA should be quite beginner-friendly.", "Model Files": [{"url": "https://huggingface.co/peteromallet/ad_motion_loras/resolve/main/plasticine-t2v.safetensors", "path": "plasticine-t2v.safetensors"}], "trigger_word": "Claymation transformation, plasticine-transforms", "Last Modified": "2025-07-26T01:18:32.856Z", "huggingface_url": "https://huggingface.co/peteromallet/ad_motion_loras/resolve/main/plasticine-t2v.safetensors", "main_generation": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492711541-y52jcqqr.mp4", "sample_generations": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492711541-y52jcqqr.mp4", "type": "video", "alt_text": "3 (3).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492712139-yhuhp9dn.mp4", "type": "video", "alt_text": "2 (3).mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492712588-a6j8mwkj.mp4", "type": "video", "alt_text": "1 (3).mp4"}]}', '2025-07-26 01:18:33.064199+00'),
	('f87a3eb5-398a-48cf-9860-1be39f1eb21b', '8a9fdac5-ed89-482c-aeca-c3dd7922d53c', 'lora', '{"Name": "Steamboat Willie", "Author": "benjamin-paine", "Images": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492906723-9f96wbf0.mp4", "type": "video", "alt_text": "ezgif-89b0b7186b49da.mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492907344-627d6ixe.mp4", "type": "video", "alt_text": "ezgif-8953dce0033205.mp4"}], "Model ID": "steamboat-willie-14b.bf16.safetensors", "filename": "steamboat-willie-14b.bf16.safetensors", "is_public": true, "lora_type": "Wan 2.1 14b", "base_model": "Wan 2.1 T2V", "created_by": {"is_you": false, "username": "benjamin-paine"}, "Description": "Trained on clips from Steamboat Willie, split by scene and captioned using Qwen2.5-VL-3B-Instruct.", "Model Files": [{"url": "https://huggingface.co/benjamin-paine/steamboat-willie-14b/resolve/main/steamboat-willie-14b.bf16.safetensors", "path": "steamboat-willie-14b.bf16.safetensors"}], "trigger_word": "steamboat willie style", "Last Modified": "2025-07-26T01:21:48.447Z", "huggingface_url": "https://huggingface.co/benjamin-paine/steamboat-willie-14b/resolve/main/steamboat-willie-14b.bf16.safetensors", "main_generation": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492906723-9f96wbf0.mp4", "sample_generations": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492906723-9f96wbf0.mp4", "type": "video", "alt_text": "ezgif-89b0b7186b49da.mp4"}, {"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753492907344-627d6ixe.mp4", "type": "video", "alt_text": "ezgif-8953dce0033205.mp4"}]}', '2025-07-26 01:21:48.709055+00'),
	('02d69fec-7ccd-4fff-8342-20c4290a7fb0', '702a2ebf-569e-4f7d-a7df-78e7c1847000', 'lora', '{"Name": "There Will Be Bloom", "Author": "You", "Images": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753493059121-1zchhy0r.mp4", "type": "video", "alt_text": "bmTtGA9mrfGexJlCtEZ71.mp4"}], "Model ID": "bloom.safetensors", "filename": "bloom.safetensors", "is_public": true, "lora_type": "Wan 2.1 14b", "base_model": "Wan 2.1 T2V", "created_by": {"is_you": true}, "Description": "Trained on timelapses of plants growing.", "Model Files": [{"url": "https://huggingface.co/peteromallet/There_Will_Be_Bloom/resolve/main/bloom.safetensors", "path": "bloom.safetensors"}], "trigger_word": "timlapsiagro", "Last Modified": "2025-07-26T01:24:20.164Z", "huggingface_url": "https://huggingface.co/peteromallet/There_Will_Be_Bloom/resolve/main/bloom.safetensors", "main_generation": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753493059121-1zchhy0r.mp4", "sample_generations": [{"url": "https://wczysqzxlwdndgxitrvc.supabase.co/storage/v1/object/public/image_uploads/files/1753493059121-1zchhy0r.mp4", "type": "video", "alt_text": "bmTtGA9mrfGexJlCtEZ71.mp4"}]}', '2025-07-26 01:24:20.358102+00'),
